import { sample, uniqueName, expect, test } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test(
    "Documents from another tenant are invisible",
    { tag: "@DOC-07" },
    async ({ apiAs }) => {
      // Arrange: a Globex vendor with an uploaded document, created by a Globex member.
      const globex = await apiAs("otherTenant");
      const vendorResponse = await globex.post("/api/vendors", {
        data: {
          name: uniqueName("Globex Vendor"),
          category: "services",
          contact_email: `billing+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@example.test`,
        },
      });
      expect(vendorResponse.status()).toBe(201);
      const vendor = await vendorResponse.json();

      const uploadResponse = await globex.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4\n% globex test document\n"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();

      // Act: a Northwind member requests the Globex document by id.
      const northwind = await apiAs("member");
      const response = await northwind.get(`/api/documents/${document.id}`);

      // Assert
      expect(response.status()).toBe(404);
      const body = await response.json();
      expect(body.error.code).toBe("document_not_found");
    },
  );
});
